using System.Security.Cryptography;using System.Text;using System.Text.Json;using SobhanNotificationHub.Models;
namespace SobhanNotificationHub.Services;public sealed class AuthTokenStore{private readonly string _path=Path.Combine(AppSettings.DataDirectory,"credentials.dat");private static readonly byte[] Entropy=Encoding.UTF8.GetBytes("Sobhan.NotificationHub.v1");public bool HasCredentials=>Load() is {DeviceUid.Length:>0,DeviceToken.Length:>0};public void Save(DeviceCredentials value){Directory.CreateDirectory(AppSettings.DataDirectory);var plain=Encoding.UTF8.GetBytes(JsonSerializer.Serialize(value));var protectedBytes=ProtectedData.Protect(plain,Entropy,DataProtectionScope.CurrentUser);File.WriteAllBytes(_path,protectedBytes);}public DeviceCredentials? Load(){try{if(!File.Exists(_path))return null;var plain=ProtectedData.Unprotect(File.ReadAllBytes(_path),Entropy,DataProtectionScope.CurrentUser);return JsonSerializer.Deserialize<DeviceCredentials>(plain);}catch(Exception ex){LoggingService.Error("credential_read",ex);return null;}}public void Clear(){try{if(File.Exists(_path))File.Delete(_path);}catch(Exception ex){LoggingService.Error("credential_clear",ex);}}}
